package com.hbm.client.network.rtty.telex;
import com.hbm.client.gui.LegacyScreen;
import com.hbm.client.gui.font.LegacyFonts;
import com.hbm.network.rtty.telex.*;
import com.mojang.blaze3d.systems.RenderSystem;
import com.mojang.blaze3d.vertex.*;
import java.util.*;
import net.minecraft.util.StringUtil;
import net.minecraft.client.gui.GuiGraphics;
import net.minecraft.client.gui.components.EditBox;
import net.minecraft.client.renderer.GameRenderer;
import net.minecraft.client.resources.sounds.SimpleSoundInstance;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.chat.Component;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.sounds.SoundEvents;
import net.neoforged.neoforge.network.PacketDistributor;
import org.lwjgl.glfw.GLFW;
/** Actual fixed7-pixel telex terminal, source formatting/control glyphs and seeded48-segment3px signal trace. */
public final class RadioTelexScreen extends LegacyScreen {
 private static final ResourceLocation TEXTURE=ResourceLocation.parse("hbm:textures/gui/machine/gui_telex.png");private final RadioTelexEntity telex;private final String[] tx=new String[5];private int left,top,cursor;private boolean textFocus;private EditBox txFrequency,rxFrequency;
 public RadioTelexScreen(RadioTelexEntity telex){super(Component.empty());this.telex=telex;System.arraycopy(telex.txBuffer,0,tx,0,5);for(int i=4;i>0;i--)if(!tx[i].isEmpty()){cursor=i;break;}}
 @Override protected void init(){font=LegacyFonts.get();left=(width-256)/2;top=(height-244)/2;txFrequency=field(top+110,telex.txChannel);rxFrequency=field(top+224,telex.rxChannel);}
 private EditBox field(int y,String value){var field=new EditBox(font,left+29,y,90,14,Component.translatable("gui.hbm.rtty.frequency"));field.setBordered(false);field.setTextColor(0x00ff00);field.setTextColorUneditable(0x00ff00);field.setMaxLength(10);field.setValue(value==null?"":value);field.setFocused(false);addWidget(field);return field;}
 private boolean at(double x,double y,int ox,int oy,int w,int h){return left+ox<=x&&x<left+ox+w&&top+oy<y&&y<=top+oy+h;}private boolean button(double x,double y,int ox,int oy){return at(x,y,ox,oy,18,18);}private int charWidth(char c){return c=='\u00a7'?-1:font.width(String.valueOf(c));}
 @Override public void render(GuiGraphics graphics,int x,int y,float partial){renderBackground(graphics,x,y,partial);graphics.blit(TEXTURE,left,top,0F,0F,256,244,256,256);if(txFrequency.isFocused())txFrequency.setFocused(true);if(rxFrequency.isFocused())rxFrequency.setFocused(true);txFrequency.render(graphics,x,y,partial);rxFrequency.render(graphics,x,y,partial);
  for(int line=0;line<5;line++){String text=tx[line],format="\u00a7r";int cy=11+14*line;for(int i=0;i<text.length();i++){char c=text.charAt(i);int cx=11+7*i+(7-charWidth(c))/2;if(c=='\u00a7'&&i+1<text.length()){format="\u00a7"+text.charAt(i+1);cx-=3;}String glyph=format+c;if(c==RadioTelexEntity.BELL)glyph="\u00a7cB";if(c==RadioTelexEntity.PRINT)glyph="\u00a7cP";if(c==RadioTelexEntity.CLEAR)glyph="\u00a7c<";if(c==RadioTelexEntity.PAUSE)glyph="\u00a7cW";graphics.drawString(font,glyph,left+cx,top+cy,0x00ff00,false);}if(System.currentTimeMillis()%1000<500&&textFocus&&cursor==line)graphics.drawString(font,"|",left+Math.max(11+7*(text.length()-1)+7,11),top+cy,0x00ff00,false);}
  for(int line=0;line<5;line++){String text=telex.rxBuffer[line],format="\u00a7r";int cx=11;for(int i=0;i<text.length();i++){char c=text.charAt(i);cx+=(7-charWidth(c))/2;if(c=='\u00a7'&&i+1<text.length()){format="\u00a7"+text.charAt(i+1);c=' ';}else if(c=='\u00a7')c=' ';else if(i>0&&text.charAt(i-1)=='\u00a7'){c=' ';cx-=14;}graphics.drawString(font,format+c,left+cx,top+145+14*line,0x00ff00,false);cx+=7;}}
  waveform(graphics);String[] actions={"bell","print_after","clear_control","format","pause"};for(int i=0;i<5;i++)if(button(x,y,7+20*i,85))graphics.renderComponentTooltip(font,List.of(Component.translatable("gui.hbm.telex."+actions[i]+".title").withStyle(net.minecraft.ChatFormatting.GOLD),Component.translatable("gui.hbm.telex."+actions[i]+".desc")),x,y);tip(graphics,x,y,127,105,"save",net.minecraft.ChatFormatting.GREEN);tip(graphics,x,y,147,105,"send",net.minecraft.ChatFormatting.YELLOW);tip(graphics,x,y,167,105,"delete",net.minecraft.ChatFormatting.RED);tip(graphics,x,y,127,219,"save",net.minecraft.ChatFormatting.GREEN);tip(graphics,x,y,147,219,"print",net.minecraft.ChatFormatting.AQUA);tip(graphics,x,y,167,219,"clear",net.minecraft.ChatFormatting.RED);
 }
 private void tip(GuiGraphics graphics,int x,int y,int ox,int oy,String key,net.minecraft.ChatFormatting color){if(button(x,y,ox,oy))graphics.renderTooltip(font,Component.translatable("gui.hbm.telex."+key).withStyle(color),x,y);}
 private void waveform(GuiGraphics graphics){graphics.flush();RenderSystem.setShader(GameRenderer::getPositionColorShader);RenderSystem.lineWidth(3F);var vertices=Tesselator.getInstance().begin(VertexFormat.Mode.DEBUG_LINES,DefaultVertexFormat.POSITION_COLOR);var matrix=graphics.pose().last().pose();var random=new Random(telex.sendingChar);double offset=0;for(int i=0;i<48;i++){vertices.addVertex(matrix,left+199+i,(float)(top+93.5+offset),10).setColor(0,255,0,255);offset=telex.sendingChar!=' '&&i>4&&i<43?Math.clamp(random.nextGaussian()*7,-7D,7D):0;vertices.addVertex(matrix,left+200+i,(float)(top+93.5+offset),10).setColor(0,255,0,255);}BufferUploader.drawWithShader(vertices.buildOrThrow());RenderSystem.lineWidth(1F);}
 @Override public boolean mouseClicked(double x,double y,int button){boolean clicked=txFrequency.mouseClicked(x,y,button)|rxFrequency.mouseClicked(x,y,button);setFocused(txFrequency.isFocused()?txFrequency:rxFrequency.isFocused()?rxFrequency:null);textFocus=at(x,y,7,7,242,74);char character=0;String command=null;char[] special={RadioTelexEntity.BELL,RadioTelexEntity.PRINT,RadioTelexEntity.CLEAR,'\u00a7',RadioTelexEntity.PAUSE};for(int i=0;i<5;i++)if(button(x,y,7+20*i,85))character=special[i];if(button(x,y,127,105)||button(x,y,127,219))command="sve";if(button(x,y,147,105))command="snd";if(button(x,y,167,105)){command="rxdel";Arrays.fill(tx,"");sendBuffers();}if(button(x,y,147,219))command="rxprt";if(button(x,y,167,219))command="rxcls";if(command!=null){click();var tag=new CompoundTag();tag.putString("cmd",command);if(command.equals("snd"))for(int i=0;i<5;i++)tag.putString("tx"+i,tx[i]);if(command.equals("sve")){tag.putString("txChan",txFrequency.getValue());tag.putString("rxChan",rxFrequency.getValue());}send(tag);}if(character!=0){click();textFocus=true;txFrequency.setFocused(false);rxFrequency.setFocused(false);setFocused(null);submit(character);}return clicked||textFocus||command!=null||character!=0;}
 private void submit(char c){if(tx[cursor].length()<RadioTelexEntity.LINE_WIDTH)tx[cursor]+=c;}
 @Override public boolean charTyped(char c,int modifiers){if(txFrequency.charTyped(c,modifiers)||rxFrequency.charTyped(c,modifiers))return true;if(textFocus&&StringUtil.isAllowedChatCharacter(c)){submit(c);return true;}return false;}
 @Override public boolean keyPressed(int key,int scan,int modifiers){if(txFrequency.keyPressed(key,scan,modifiers)||rxFrequency.keyPressed(key,scan,modifiers))return true;if(textFocus){if(key==GLFW.GLFW_KEY_ESCAPE){textFocus=false;return true;}if(key==GLFW.GLFW_KEY_UP)cursor=Math.max(0,cursor-1);if(key==GLFW.GLFW_KEY_DOWN)cursor=Math.min(4,cursor+1);if(key==GLFW.GLFW_KEY_BACKSPACE&&!tx[cursor].isEmpty())tx[cursor]=tx[cursor].substring(0,tx[cursor].length()-1);return key==GLFW.GLFW_KEY_UP||key==GLFW.GLFW_KEY_DOWN||key==GLFW.GLFW_KEY_BACKSPACE;}if(key==GLFW.GLFW_KEY_ESCAPE||!txFrequency.isFocused()&&!rxFrequency.isFocused()&&minecraft.options.keyInventory.matches(key,scan)){onClose();return true;}return false;}
 private void click(){minecraft.getSoundManager().play(SimpleSoundInstance.forUI(SoundEvents.UI_BUTTON_CLICK,1F));}private void send(CompoundTag tag){PacketDistributor.sendToServer(new RadioTelexControl(telex.getBlockPos(),tag));}private void sendBuffers(){var tag=new CompoundTag();for(int i=0;i<5;i++)tag.putString("tx"+i,tx[i]);send(tag);}@Override public void removed(){sendBuffers();super.removed();}@Override public boolean isPauseScreen(){return false;}
}
